    try: refund_shipping(mk(),bad,T0); print("FAIL")
    except BillingError as e: print("nonpositive:",e.code)

try: refund_shipping(mk(),Decimal("101.00"),T0)
except BillingError as e: print("over:",e.code)

try: refund_shipping(mk("1000.00"),Decimal("600.00"),T0)
except BillingError as e: print("approval:",e.code)
p=mk("1000.00"); refund_shipping(p,Decimal("600.00"),T0,approved_by="mgr"); print("approved ok",p.refunded_amount)

p=mk(); refund_shipping(p,Decimal("10.00"),T0,idempotency_key="k1"); refund_shipping(p,Decimal("10.00"),T0,idempotency_key="k1")
